#pragma once

// What OpenRocket's launch conditions panel shows and does: the transcript of the probe
// tools/openrocket-probes/simulation-conditions (SimulationConditionsProbe, OpenRocket 5f164fd0e,
// SwingPreferences of a fresh store, FlatLaf Light, headless), its WALK, STEP, HANDLER and SUMMARY
// lines section by section ("== <section>" there), pinned by hand: copied from its expected.txt
// with the non-ASCII characters written as escapes. The probe's MODEL and BOX lines are pinned
// in SimulationConditionsPanelTests.cpp as expectations of their own. A change of the probe's
// transcript is reviewed against these pins (tools/openrocket-probes/README.md).

#include <array>
#include <string_view>

